records.handler_text:
listUsers = async (request: FastifyRequest, reply: FastifyReply) => {
  try {
    const { page = 1, limit = 10, search, status, plan, isGuest } = request.query as any;
    const skip = (Number(page) - 1) * Number(limit);
    const take = Number(limit);

    const where: any = {};
    if (search) {
      where.OR = [
        { email: { contains: search, mode: 'insensitive' } },
        { fullName: { contains: search, mode: 'insensitive' } },
      ];
    }
    if (status) where.status = status;
    if (plan) where.plan = plan;
    if (isGuest !== undefined) where.isGuest = isGuest === 'true';

    const [users, total] = await Promise.all([
      prisma.user.findMany({
        where,
        skip,
        take,
        select: {
          id: true,
          email: true,
          fullName: true,
          avatarUrl: true,
          plan: true,
          userClass: true,
          status: true,
          isGuest: true,
          lastLoginAt: true,
          createdAt: true,
          twoFactorEnabled: true,
          authProvider: true
        },
        orderBy: { createdAt: 'desc' }
      }),
      prisma.user.count({ where })
    ]);

    return reply.send({ data: users, meta: { total, page: Number(page), limit: take } });
  } catch (error: any) {
    request.log.error(error);
    return reply.status(500).send({ message: 'Failed to list users', error: error.message });
  }
}

